function read(a:(i32|undefined)[],i:u32):i32|undefined{return a[i];}
function readDeadOnly(a:(i32|undefined)[],i:u32):i32|undefined{return a[i];}
export function runIf():i32|undefined{const dead:(i32|undefined)[]=[undefined];if(false){read(dead,0);}const live:(i32|undefined)[]=[1];return read(live,0);}
export function runWhile():i32|undefined{const dead:(i32|undefined)[]=[undefined];while(false){read(dead,0);}const live:(i32|undefined)[]=[1];return read(live,0);}
export function runAnd():i32|undefined{const dead:(i32|undefined)[]=[undefined];false&&(read(dead,0)===undefined);const live:(i32|undefined)[]=[1];return read(live,0);}
export function runOr():i32|undefined{const dead:(i32|undefined)[]=[undefined];true||(read(dead,0)===undefined);const live:(i32|undefined)[]=[1];return read(live,0);}
export function runDeadOnly():i32{const dead:(i32|undefined)[]=[undefined];if(false){readDeadOnly(dead,0);}return 0;}
export function runUnknown(flag:bool):i32|undefined{const dead:(i32|undefined)[]=[undefined];if(flag){read(dead,0);}const live:(i32|undefined)[]=[1];return read(live,0);}
